arguments.command:
cd /tmp/vally-eval-trial-MkTuQf && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-10-06 $P/evidence/2026-10-06/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/checkout-pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED  : AC-1, AC-2, AC-3 (tier prices on a 10000 cent subtotal)
  # UNSETTLED: AC-4 (rounding) - its title and its expected value disagree, see below
  # UNDECIDED: Platinum tier - no reduction agreed, deliberately NO scenario (no value may be invented)

  @happy-path @smoke
  Scenario: Bronze customer is charged 9500 cents on a 10000 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged 9000 cents on a 10000 cent basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged 8500 cents on a 10000 cent basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # NEEDS CLARIFICATION (escalate to DISCUSS): AC-4 is titled "Reduction lands on a whole cent in the
  # customer's favour" yet expects 7 cents charged on a 7 cent basket (reduction rounded down to 0).
  # Rounding in the customer's favour would remove 1 cent (6 charged). Value copied verbatim from the
  # AC but NOT approved for implementation until the business confirms it.
  @edge-case @needs-clarification
  Scenario: Bronze customer is charged 7 cents on a 7 cent basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged 9500 cents on a 10000 cent basket
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_tier_price(LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
ls $P/features tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount

